let demoState;try{const stored=JSON.parse(localStorage.getItem('imovel-em-dia-demo-v1'));demoState=stored&&stored.user&&['properties','items','issues','purchases','finance','audit'].every(k=>Array.isArray(stored[k]))?stored:clone(demoSeed)}catch{demoState=clone(demoSeed)}
const uid=()=>globalThis.crypto?.randomUUID?.()||String(Date.now())+Math.random();
function persist(){try{localStorage.setItem('imovel-em-dia-demo-v1',JSON.stringify(demoState))}catch{}}
async function localApi(path,d,key){if(path==='state')return clone(demoState);if(path==='logout'){demoState=clone(demoSeed);persist();page='overview';return {ok:true}};
const s=clone(demoState);const check=(b,msg)=>{if(!b)throw new Error(msg)};const get=(arr,id)=>{const x=arr.find(v=>v.id===id);check(x,'Registro não encontrado.');return x};const add=(arr,x)=>{x.id=Math.max(0,...arr.map(v=>v.id))+1;arr.unshift(x);return x};const timestamp=new Date().toISOString();const log=(action,details)=>add(s.audit,{action,details,actor:s.user.name,created:timestamp});const valid=n=>Number.isInteger(n)&&n>=0;const live=p=>check(!p.archived,'Imóvel arquivado.');
function sync(i){let issue=s.issues.find(x=>x.item_id===i.id&&openIssue(x));if(gap(i)>0){if(!issue)issue=add(s.issues,{property_id:i.property_id,item_id:i.id,title:'Repor '+i.name,priority:'Normal',status:'Aberta',created:timestamp});issue.description='Reposição necessária: '+gap(i)+' unidade(s).';if(issue.status==='Aguardando conferência')issue.status='Aberta'}else if(issue){issue.status='Aguardando conferência';issue.description='Quantidade necessária atingida. Confirme a reposição.'}return issue?.id}
let id;
if(path==='properties'){check(d.name?.trim(),'Informe a identificação.');if(d.id){Object.assign(get(s.properties,d.id),d);id=d.id}else{id=add(s.properties,{...d,archived:0}).id}log('Imóvel salvo',d.name)}
else if(path==='properties/archive'){const p=get(s.properties,d.id);p.archived=d.archived;id=p.id;log(d.archived?'Imóvel arquivado':'Imóvel restaurado',p.name)}
else if(path==='items'){const p=get(s.properties,d.property_id);live(p);check(d.name?.trim()&&d.room?.trim()&&d.category?.trim(),'Preencha nome, cômodo e categoria.');check([d.needed,d.quantity,d.damaged].every(valid)&&d.damaged<=d.quantity,'Confira as quantidades.');let i;if(d.id){i=get(s.items,d.id);check(i.property_id===p.id,'Não é possível transferir por edição.');Object.assign(i,d)}else i=add(s.items,{...d});id=i.id;sync(i);log('Inventário conferido',p.name+': '+i.name)}
else if(path==='issues'){live(get(s.properties,d.property_id));check(d.title?.trim(),'Informe o título.');id=add(s.issues,{...d,status:'Aberta',created:timestamp}).id;log('Pendência criada',d.title)}
else if(path==='issues/status'){const i=get(s.issues,d.id);const allowed={'Aberta':['Em andamento','Aguardando conferência','Cancelada'],'Em andamento':['Aberta','Aguardando conferência','Cancelada'],'Aguardando conferência':['Resolvida','Aberta','Cancelada'],'Resolvida':['Aberta'],'Cancelada':['Aberta']};check(allowed[i.status].includes(d.status)&&d.note?.trim(),'Informe uma transição e justificativa válidas.');check(d.status!=='Resolvida'||!i.item_id||gap(get(s.items,i.item_id))===0,'Ainda há itens em falta.');if(d.status==='Aberta'&&i.item_id)check(!s.issues.some(x=>x.id!==i.id&&x.item_id===i.item_id&&openIssue(x)),'Já existe uma pendência aberta para este item.');i.status=d.status;id=i.id;log('Pendência: '+d.status,i.title+' — '+d.note)}
else if(path==='purchases'){const i=get(s.items,d.item_id);live(get(s.properties,i.property_id));const pending=s.purchases.filter(p=>p.item_id===i.id&&!['Recebida','Cancelada'].includes(p.status)).reduce((a,p)=>a+p.quantity-p.received,0);check(valid(d.quantity)&&d.quantity>0&&d.quantity<=gap(i)-pending,'Quantidade supera a necessidade ainda não coberta.');check(valid(d.cost),'Valor inválido.');id=add(s.purchases,{...d,issue_id:sync(i),received:0,paid:0,status:'Solicitada',created:timestamp}).id;log('Compra solicitada',d.quantity+' × '+i.name)}
else if(path.startsWith('purchases/')){const p=get(s.purchases,d.id),i=get(s.items,p.item_id),a=path.split('/')[1];id=p.id;if(a==='approve'){check(p.status==='Solicitada','Compra não está aguardando aprovação.');p.status='Aprovada'}else if(a==='cancel'){check(['Solicitada','Aprovada'].includes(p.status)&&!p.paid&&!p.received,'Não é possível cancelar uma compra paga ou recebida.');p.status='Cancelada'}else if(a==='receive'){check(['Aprovada','Parcialmente recebida'].includes(p.status)&&valid(d.quantity)&&d.quantity>0&&d.quantity<=p.quantity-p.received,'Confira a quantidade e a aprovação.');p.received+=d.quantity;i.quantity+=d.quantity;p.status=p.received===p.quantity?'Recebida':'Parcialmente recebida';sync(i)}else if(a==='pay'){check(['Aprovada','Parcialmente recebida','Recebida'].includes(p.status)&&!p.paid&&valid(d.cost)&&d.cost>0&&d.date,'Pagamento não permitido.');add(s.finance,{property_id:i.property_id,purchase_id:p.id,kind:'Despesa',title:'Compra: '+i.name,amount:d.cost,date:d.date});p.paid=1;p.cost=d.cost}else throw new Error('Ação desconhecida.');log(({approve:'Compra aprovada',cancel:'Compra cancelada',receive:'Recebimento confirmado',pay:'Pagamento registrado'})[a],i.name+' · compra '+p.id)}
else if(path==='finance'){get(s.properties,d.property_id);check(d.title?.trim()&&valid(d.amount)&&d.amount>0&&d.date,'Confira os dados do lançamento.');id=add(s.finance,{...d}).id;log('Lançamento financeiro',d.title)}else throw new Error('Ação indisponível na demonstração.');demoState=s;persist();return {id}}
const remote=location.protocol!=='file:'&&!location.pathname.includes('demo')&&document.documentElement.dataset.mode==='server';
async function api(path,d,key){if(!remote)return localApi(path,d,key);const r=await fetch('/api/'+path,{method:d===undefined?'GET':'POST',headers:d===undefined?{}:{'Content-Type':'application/json','Idempotency-Key':key||uid()},body:d===undefined?undefined:JSON.stringify(d),credentials:'same-origin'});const out=await r.json();if(!r.ok){const err=Error(out.error||'Não foi possível concluir.');err.status=r.status;throw err}return out}
async function load(){try{state=await api('state');if(remote)demoState=state;render()}catch(err){if(err.status===401)auth();else if(root.querySelector('.fallback')){document.querySelector('#preview-note').textContent='Modo de leitura: o navegador não iniciou as funções interativas. Dados fictícios.';}else root.innerHTML=`<div class="loading"><p>${e(err.message)}</p>${btn('Tentar novamente','reload')}</div>`}}
function auth(){state=null;root.innerHTML=`<main class="auth"><section class="intro">${brand()}<div><h1>Cuide de cada imóvel, sem perder nenhum detalhe.</h1><p>Inventário, pendências, compras e despesas conectados em um só lugar. Saiba o que falta e acompanhe cada solução.</p></div><svg class="houseart" viewBox="0 0 360 165" fill="none" stroke="currentColor" stroke-width="1.4" aria-hidden="true"><path d="M8 145h344M55 145V70l77-54 77 54v75M85 145V87h48v58M157 83h29v29h-29zM209 145V92l46-32 46 32v53M229 111h23v34M268 103h18v20h-18zM20 145v-35m-12 15h24m287 20v-50m-15 22h30M47 73l85-60 85 60"/><path d="M105 111h5M10 145c-7-20 23-21 20 0M309 145c-12-21 29-25 28 0"/></svg><span class="authfoot">Organização que acompanha o trabalho de verdade.</span></section><section class="authright"><form class="authform" id="authform"><div class="eyebrow">Sua área de trabalho</div><h2>${authMode==='login'?'Acesse sua conta':'Crie sua organização'}</h2><p class="muted">${authMode==='login'?'Entre para continuar de onde parou.':'Comece com um espaço de trabalho independente.'}</p>${authMode==='register'?field('name','Seu nome','text','',true)+field('organization','Nome da organização','text','',true):''}${field('email','E-mail','email','',true)}${field('password','Senha','password','',true)}${authMode==='register'?'<p class="muted subtle">Utilize pelo menos 12 caracteres.</p>':''}<p id="auth-error" role="alert"></p><button type="submit">${authMode==='login'?'Entrar':'Criar conta'}</button><button type="button" class="switch" data-action="switch">${authMode==='login'?'Ainda não tem conta? Cadastre-se':'Já tem conta? Entrar'}</button></form></section></main>`;$('#authform').addEventListener('submit',async ev=>{ev.preventDefault();const f=ev.currentTarget,b=f.querySelector('[type=submit]');b.disabled=true;try{await api(authMode==='login'?'login':'register',Object.fromEntries(new FormData(f)));page='overview';await load()}catch(err){$('#auth-error').textContent=err.message;b.disabled=false}})}
function field(name,label,type='text',value='',required=false,options=[]){return `<div class="field"><label for="f-${name}">${e(label)}</label>${type==='select'?`<select id="f-${name}" name="${name}" ${required?'required':''}>${options.map(o=>{const [v,l]=Array.isArray(o)?o:[o,o];return `<option value="${e(v)}" ${String(v)===String(value)?'selected':''}>${e(l)}</option>`}).join('')}</select>`:type==='textarea'?`<textarea id="f-${name}" name="${name}" ${required?'required':''}>${e(value)}</textarea>`:`<input id="f-${name}" name="${name}" type="${type}" value="${e(value)}" ${required?'required':''} ${type==='number'?'min="0" step="any"':''} ${type==='password'?'autocomplete="current-password"':''}>`}</div>`}
function render(){if(!state)return;root.innerHTML=`<div class="shell"><aside class="sidebar ${mobileOpen?'open':''}">${brand()}<div class="workspace"><div class="eyebrow">Organização</div><strong>${e(state.user.organization)}</strong></div><div class="navlabel">Área de trabalho</div><nav class="nav">${nav.map(([k,l])=>`<button class="${page===k?'active':''}" data-action="nav" data-id="${k}" ${page===k?'aria-current="page"':''}>${svg(k)}${l}</button>`).join('')}</nav><div class="user"><strong>${e(state.user.name)}</strong><span class="muted subtle">${e(state.user.email)}</span>${btn('Reiniciar demonstração','logout')}</div></aside><main class="content"><header class="top"><div>${btn('Menu','menu','','secondary menu-toggle')} <span class="muted">${e(nav.find(x=>x[0]===page)?.[1]||(page==='property'?'Detalhes do imóvel':''))}</span></div><span class="demo-label">Demonstração · dados fictícios</span><span class="muted subtle top-date">${e(new Date().toLocaleDateString('pt-BR',{day:'numeric',month:'long',year:'numeric'}))}</span></header><div id="view">${view()}</div></main></div>`;wireFilters()}
function toolbar(){return `<div class="toolbar"><input id="search" type="search" placeholder="Pesquisar nesta área" aria-label="Pesquisar nesta área" value="${e(search)}"><select id="property-filter" aria-label="Filtrar por imóvel"><option value="">Todos os imóveis</option>${state.properties.map(p=>`<option value="${p.id}" ${String(p.id)===filter?'selected':''}>${e(p.name)}</option>`).join('')}</select></div>`}
