root.addEventListener('click',async ev=>{const b=ev.target.closest('[data-action]');if(!b)return;const a=b.dataset.action,raw=b.dataset.id||'',id=Number(raw);if(!['extra-new','extra-edit','extra-issue','stock-new','stock-edit','stock-add','stock-transfer','backup','print-report','profile','notifications'].includes(a))return;ev.stopImmediatePropagation();try{if(a==='extra-new')extraForm(raw||page);if(a==='extra-edit'){const [k,i]=raw.split(':');extraForm(k,Number(i))}if(a==='extra-issue'){const [k,i]=raw.split(':'),r=demoState[k].find(x=>x.id===Number(i));modal('Gerar pendência',field('title','Título','text',r.title,true)+field('description','Descrição','textarea',r.notes||'')+field('priority','Prioridade','select','Normal',true,['Baixa','Normal','Alta','Urgente']),async d=>{if(remote)return api('extra/issue',{module:k,id:r.id,...d});commitLocal('Pendência gerada',d.title,s=>{const x=s[k].find(v=>v.id===r.id);if(x.issue_id)throw Error('Já existe uma pendência vinculada.');const issue={id:nextId(s.issues),property_id:r.property_id,...d,status:'Aberta',due:r.date||null,created:new Date().toISOString()};s.issues.unshift(issue);x.issue_id=issue.id;if(k==='inbox')x.status='Convertida'})})}if(a==='stock-new'||a==='stock-edit')stockForm(id);if(a==='stock-add'||a==='stock-transfer')stockTransfer(id,a==='stock-add');if(a==='backup')downloadJSON();if(a==='print-report')window.print();if(a==='profile')modal('Editar perfil',field('name','Seu nome','text',state.user.name,true)+field('organization','Organização','text',state.user.organization,true),async d=>remote?api('profile',d):commitLocal('Perfil atualizado',d.organization,s=>Object.assign(s.user,d)));if(a==='notifications'){modal('Notificações',eventList().slice(0,8).map(r=>`<div class="event"><span class="event-day">${date(r.date).slice(0,5)}</span><div><strong>${e(r.title)}</strong><small>${e(r.kind)} · ${e(r.detail)}</small></div></div>`).join('')||'<p>Sem notificações.</p>',async()=>{});$('#save').style.display='none';$('#cancel').textContent='Fechar'}}catch(err){toast(err.message)}},true);

