const steps=[['Cadastre seu primeiro imóvel','Identifique o endereço e a situação de ocupação.','properties',()=>activeProps().length>0],['Monte o inventário','Informe o que deve existir e o que está disponível.','items',()=>state.items.length>0],['Registre uma pendência','Indique um problema, prazo ou necessidade de reposição.','issues',()=>state.issues.length>0],['Organize as compras','Acompanhe aprovação, pagamento e recebimento.','purchases',()=>state.purchases.length>0],['Confira as despesas','Registre entradas e saídas associadas aos imóveis.','finance',()=>state.finance.length>0]];
function guideView(){const done=steps.filter(x=>x[3]()).length;return heading('Primeiros passos','Configure os imóveis e acompanhe as etapas de implantação.')+`<section class="guide-intro"><div><span class="eyebrow">Configuração inicial</span><h2>Comece a organizar tudo em ordem?</h2><p>Comece com um imóvel. O restante do sistema acompanha suas informações.</p></div><strong>${done} de ${steps.length} etapas</strong></section><div class="panel guide-list">${steps.map(([t,d,p,ok],i)=>`<div class="guide-step"><span class="step-number ${ok()?'complete':''}">${ok()?'✓':i+1}</span><div><h3>${e(t)}</h3><p>${e(d)}</p></div>${btn(ok()?'Revisar':'Começar','nav',p,'secondary small')}</div>`).join('')}</div>`+panel('Precisa de ajuda?',`<div class="panelbody"><p>O assistente explica os recursos e ajuda a transformar anotações em pendências.</p><p style="margin-top:12px">${btn('Conversar com o assistente','nav','assistant','')}</p></div>`)}
let chat=[], proposals=[], assistantBusy=false;
function localAnswer(q){const n=norm(q), props=activeProps(), matched=props.filter(p=>n.includes(norm(p.name)));const use=matched.length?matched:props;const ids=new Set(use.map(p=>p.id));let answer='', suggestions=[];if(/falt|utens|inventario|repor/.test(n)&&!/registr|criar|anot/.test(n)){const rows=state.items.filter(i=>ids.has(i.property_id)&&gap(i)>0);answer=rows.length?rows.map(i=>`${pname(i.property_id)}: ${gap(i)} × ${i.name}`).join('\n'):'Nenhuma falta registrada nos imóveis consultados.'}else if(/gast|despes|finance|receit/.test(n)&&!/registr|criar/.test(n)){const rows=state.finance.filter(f=>ids.has(f.property_id));answer=`Total registrado (todos os períodos): receitas ${money(rows.filter(f=>f.kind==='Receita').reduce((a,f)=>a+f.amount,0))}; despesas ${money(rows.filter(f=>f.kind==='Despesa').reduce((a,f)=>a+f.amount,0))}.`}else if(/registr|criar|anot|precisa|consert/.test(n)&&matched.length===1){suggestions=[{property_id:matched[0].id,title:q.slice(0,110),description:q,priority:'Normal'}];answer='Preparei uma pendência com o imóvel identificado. Revise o título, descrição e prioridade antes de salvar.'}else if(/pendenc|atras|prioridad/.test(n)){const rows=state.issues.filter(i=>ids.has(i.property_id)&&openIssue(i));answer=rows.length?rows.map(i=>`${pname(i.property_id)}: ${i.title} (${i.status})`).join('\n'):'Não há pendências abertas nos imóveis consultados.'}else if(/compra|recebimento/.test(n)){answer='Em Compras, solicite a quantidade necessária. Aprove o pedido antes de registrar o recebimento; o inventário será atualizado. Registre o pagamento separadamente para atualizar o financeiro.'}else{answer='Posso listar itens faltantes, pendências e valores registrados. Para preparar uma pendência, informe o nome exato do imóvel e descreva o problema. Use Primeiros passos para conhecer os fluxos.'}return {answer,suggestions,mode:'local'}}
function assistantView(){return heading('Assistente de operação','Pergunte sobre seus imóveis ou descreva uma tarefa.')+`<div class="assistant-layout"><section class="panel chat-panel"><div class="paneltitle"><div><h2>Como posso ajudar?</h2><p class="muted subtle">${remote&&state.ai_enabled?'IA configurada · confirme as sugestões antes de salvar':'Ajuda local baseada em regras · sem modelo de IA conectado'}</p></div></div><div class="chat-body" aria-live="polite">${chat.length?chat.map(m=>`<div class="chat-msg ${m.who==='Você'?'mine':''}"><strong>${e(m.who)}</strong><p>${e(m.text)}</p></div>`).join(''):'<div class="chat-welcome"><h3>Comece com uma pergunta</h3><p>Você pode consultar as informações já cadastradas ou preparar uma nova pendência.</p></div>'}${assistantBusy?'<p class="muted">Consultando informações…</p>':''}</div><form id="assistant-form" class="chat-form"><label for="assistant-q" class="eyebrow">Sua pergunta ou anotação</label><textarea id="assistant-q" required maxlength="2000" placeholder="Ex.: Quais itens estão faltando?" ${assistantBusy?'disabled':''}></textarea><button type="submit" ${assistantBusy?'disabled':''}>Enviar</button></form></section><div>${panel('Sugestões de perguntas',`<div class="panelbody suggestion-buttons">${['Quais itens estão faltando?','Quais pendências estão abertas?','Quanto foi gasto e recebido?','Como funciona uma compra?'].map(q=>`<button class="secondary" data-action="ask" data-id="${e(q)}">${e(q)}</button>`).join('')}</div>`)}${panel('Ações para revisar',proposals.length?proposals.map((p,i)=>`<div class="entry"><div><strong>${e(p.title)}</strong><small>${e(pname(p.property_id))}</small></div>${btn('Revisar','proposal',i)}</div>`).join(''):'<div class="panelbody muted">As sugestões aparecerão aqui. Nada é registrado sem sua confirmação.</div>')}</div></div>`}
async function ask(q){if(!q.trim()||assistantBusy)return;if(remote&&state.ai_enabled&&!chat.length&&!confirm('Enviar sua pergunta e um resumo operacional dos imóveis ao provedor de IA configurado? Não inclua dados pessoais ou informações confidenciais.'))return;chat.push({who:'Você',text:q});assistantBusy=true;render();try{const r=remote&&state.ai_enabled?await api('assistant',{question:q}):localAnswer(q);chat.push({who:r.mode==='local'?'Ajuda local':'Assistente',text:r.answer});proposals=(r.suggestions||[]).filter(p=>activeProps().some(x=>x.id===p.property_id));}catch(err){chat.push({who:'Assistente',text:'Não consegui responder: '+err.message})}finally{assistantBusy=false;render()}}
const prevView=view;view=function(){if(page==='guide')return guideView();if(page==='assistant')return assistantView();if(page==='overview'){const done=steps.filter(x=>x[3]()).length;const banner=`<div class="guide-banner"><div><strong>${done===5?'Seu guia de organização':'Comece por aqui'}</strong><p>${done} de 5 etapas concluídas. Aprenda a usar as ferramentas conforme sua rotina.</p></div>${btn('Abrir guia','nav','guide','secondary')}</div>`;return done<5?banner+dashboard():dashboard()+banner}return prevView()};
