settingsView=function(){return heading('Configurações','Gerencie seu perfil e suas informações.')+panel('Organização',`<div class="panelbody"><p><strong>${e(state.user.organization)}</strong></p><p>${e(state.user.name)}</p><div class="rowactions" style="margin-top:15px">${btn('Editar perfil','profile')}${btn('Exportar dados','backup')}${btn(remote?'Sair da conta':'Restaurar demonstração','logout')}</div></div>`)+panel('Privacidade',`<div class="panelbody"><p>${remote?'Os registros são armazenados no servidor desta instalação e vinculados à sua organização.':'Esta demonstração utiliza dados fictícios e armazenamento local. Não insira informações reais.'}</p></div>`)};
plansView=function(){const billing=state.billing||{};return heading('Planos e assinatura','Escolha o espaço de trabalho adequado à sua operação.')+`<div class="guide-banner"><div><strong>Plano atual: ${e(billing.label||'Demonstração')}</strong><p>${remote?'Imóveis ativos: '+activeProps().length+' / '+(billing.limit||1):'Nenhuma cobrança será realizada nesta demonstração.'}</p></div>${remote&&billing.enabled?btn('Consultar pagamento','billing-refresh','','secondary'):''}</div><div class="properties plan-grid">${[['free','Gratuito','0','1 imóvel','Inventário e pendências'],['essential','Essencial','39,90','Até 5 imóveis','Controle de compras e manutenção'],['professional','Profissional','79,90','Até 20 imóveis','Gestão imobiliária ampliada'],['business','Empresarial','149,90','Até 60 imóveis','Mais capacidade para equipes']].map(([k,n,p,q,f])=>`<section class="panel plan"><div class="panelbody"><p class="eyebrow">${e(n)}</p><h2>R$ ${p}<small> / 30 dias</small></h2><p>${q}</p><p class="muted">${f}</p>${k==='free'?'':remote&&billing.enabled?btn('Gerar cobrança Pix','checkout',k,''): '<p class="muted subtle">Contratação ainda indisponível</p>'}</div></section>`).join('')}</div><p class="muted">Pix avulso com renovação manual. O plano é liberado após confirmação de recebimento pelo Asaas. Os limites pagos nesta versão referem-se ao número de imóveis ativos.</p>${billing.pending?panel('Cobrança em aberto',`<div class="panelbody"><p>${e(billing.pending.label)} · ${money(billing.pending.amount)}</p>${billing.pending.invoice?`<a href="${e(billing.pending.invoice)}" target="_blank" rel="noopener noreferrer">Abrir fatura Pix</a>`:''}</div>`):''}`};
root.addEventListener('click',async ev=>{const b=ev.target.closest('[data-action]');if(!b)return;const a=b.dataset.action;if(!['ask','proposal','checkout','billing-refresh','demo-enter'].includes(a))return;ev.stopImmediatePropagation();try{if(a==='ask')await ask(b.dataset.id);if(a==='proposal'){const p=proposals[Number(b.dataset.id)];if(!p)return;modal('Revisar pendência',propSelect(p.property_id)+field('title','Título','text',p.title,true)+field('description','Descrição','textarea',p.description||'')+field('priority','Prioridade','select',p.priority||'Normal',true,['Baixa','Normal','Alta','Urgente']),async(d,key)=>{await api('issues',{...d,property_id:Number(d.property_id)},key);proposals=proposals.filter(x=>x!==p)})}if(a==='checkout'){modal('Pagamento Pix',`<p>O Asaas utilizará os dados do pagador para criar a cobrança. Não haverá renovação automática.</p>`+field('cpf','CPF ou CNPJ do pagador','text','',true),async(d,key)=>{await api('billing/checkout',{plan:b.dataset.id,cpf:d.cpf},key);toast('Cobrança criada. Abra a fatura na página de planos.')})}if(a==='billing-refresh'){await api('billing/refresh',{});await load();toast('Situação consultada.')}if(a==='demo-enter'){location.href='/demo'}}catch(err){toast(err.message)}},true);
