function opsCards(values){return `<div class="ops-metrics">${values.map(([l,v,d])=>`<article><small>${e(l)}</small><strong>${e(v)}</strong><span>${e(d)}</span></article>`).join('')}</div>`}
function operationsView(k){const rows=opsRows(k);if(k==='reservations'){const live=rows.filter(isBooking);return heading('Reservas','Acompanhe entradas e saídas sem sobreposição de períodos.',btn('Nova reserva','ops-new',k,''))+opsCards([['Confirmadas',live.length,'Reservas ativas'],['Entradas futuras',live.filter(r=>r.arrival>=localDate()).length,'A partir de hoje'],['Em estadia',live.filter(r=>r.arrival<=localDate()&&r.departure>localDate()).length,'Ocupação por reserva']])+toolbar()+panel('Agenda de reservas',rows.length?table(['Hóspede / imóvel','Entrada','Saída','Situação','Ações'],rows.slice().sort((a,b)=>a.arrival.localeCompare(b.arrival)).map(r=>[`${e(r.guest)}<br><small class="muted">${e(pname(r.property_id))}</small>`,date(r.arrival),date(r.departure),tag(r.status,r.status==='Cancelada'?'neutral':''),`<div class="rowactions">${isBooking(r)?(r.departure<=localDate()?btn('Concluir','ops-status',k+':'+r.id+':Concluída'):'')+btn('Cancelar','ops-status',k+':'+r.id+':Cancelada'):'—'}</div>`])):empty('Nenhuma reserva','Crie uma reserva para organizar suas entradas e saídas.','ops-new','Nova reserva'))}const open=rows.filter(r=>r.status==='Aberta');return heading('Contas a receber','Controle vencimentos e registre a entrada no caixa apenas quando receber.',btn('Nova cobrança','ops-new',k,''))+opsCards([['A receber',money(open.reduce((a,r)=>a+r.amount,0)),'Valores em aberto'],['Em atraso',money(open.filter(isOverdue).reduce((a,r)=>a+r.amount,0)),'Vencimentos anteriores a hoje'],['Recebido',money(rows.filter(r=>r.status==='Recebida').reduce((a,r)=>a+r.amount,0)),'Já registrado no caixa']])+toolbar()+panel('Cobranças',rows.length?table(['Descrição / pagador','Imóvel','Vencimento','Valor','Situação','Ações'],rows.slice().sort((a,b)=>a.due.localeCompare(b.due)).map(r=>[`${e(r.title)}<br><small class="muted">${e(r.payer)}</small>`,e(pname(r.property_id)),date(r.due),money(r.amount),tag(isOverdue(r)?'Em atraso':r.status,isOverdue(r)?'bad':r.status==='Aberta'?'warn':''),r.status==='Aberta'?`<div class="rowactions">${btn('Registrar recebimento','ops-status',k+':'+r.id+':Recebida')}${btn('Cancelar','ops-status',k+':'+r.id+':Cancelada')}</div>`:'—'])):empty('Nenhuma cobrança','Cadastre um valor a receber.','ops-new','Nova cobrança'))}
