function propertyWorkspace(){const p=prop(selectedProperty);if(!p)return heading('Imóvel não encontrado','Volte à lista de imóveis.',btn('Voltar','nav','properties'));const own=k=>records(k).filter(r=>r.property_id===p.id),issues=own('issues').filter(openIssue),items=own('items'),r=own('receivables').filter(x=>x.status==='Aberta'),f=own('finance'),balance=f.reduce((a,x)=>a+(x.kind==='Receita'?x.amount:-x.amount),0),book=own('reservations').filter(isBooking).sort((a,b)=>a.arrival.localeCompare(b.arrival));return `<div class="property-hero"><div>${btn('Todos os imóveis','nav','properties')}<div class="eyebrow">${e(p.kind)} · ${e(p.archived?'Arquivado':p.occupancy)}</div><h1>${e(p.name)}</h1><p>${e(p.address||'Endereço não informado')}</p></div>${btn('Editar imóvel','property-edit',p.id,'secondary')}</div>`+opsCards([['Pendências',issues.length,'Em aberto'],['Inventário',items.reduce((a,i)=>a+gap(i),0)+' em falta',items.length+' tipos de item'],['A receber',money(r.reduce((a,x)=>a+x.amount,0)),'Cobranças abertas'],['Resultado de caixa',money(balance),'Receitas menos despesas']])+`<div class="workspace-links">${[['items','Inventário'],['issues','Pendências'],['reservations','Reservas'],['receivables','Contas a receber'],['maintenance','Manutenção'],['inspections','Vistorias'],['cleaning','Limpeza'],['finance','Finanças'],['contracts','Contratos'],['documents','Documentos']].map(([k,l])=>`<button class="secondary" data-action="property-section" data-id="${k}">${svg(k)} ${e(l)}</button>`).join('')}</div><div class="dash-grid">${panel('Pendências em aberto',issues.slice(0,6).map(i=>`<div class="entry"><div><strong>${e(i.title)}</strong><small>${e(i.status)} · ${date(i.due)}</small></div>${tag(i.priority,'warn')}</div>`).join('')||empty('Tudo em dia','Não há pendências abertas.'))}${panel('Reservas confirmadas',book.slice(0,6).map(i=>`<div class="entry"><div><strong>${e(i.guest)}</strong><small>${date(i.arrival)} a ${date(i.departure)}</small></div>${tag(i.status)}</div>`).join('')||empty('Sem reservas','Não há reservas confirmadas.'))}</div>`}
const oldEvents=eventList;eventList=function(){return [...oldEvents(),...records('reservations').filter(isBooking).flatMap(r=>[{date:r.arrival,title:'Entrada · '+r.guest,detail:pname(r.property_id),kind:'Reserva',page:'reservations'},{date:r.departure,title:'Saída · '+r.guest,detail:pname(r.property_id),kind:'Reserva',page:'reservations'}]),...records('receivables').filter(r=>r.status==='Aberta').map(r=>({date:r.due,title:r.title,detail:pname(r.property_id),kind:'Cobrança',page:'receivables'}))].sort((a,b)=>a.date.localeCompare(b.date))};
const lastView=view;view=function(){if(page==='reservations'||page==='receivables')return operationsView(page);if(page==='property')return propertyWorkspace();if(page==='overview'){const overdue=records('receivables').filter(isOverdue),arrivals=records('reservations').filter(r=>isBooking(r)&&r.arrival>=localDate()&&r.arrival<=dayOffset(7));return `<div class="ops-alerts"><button class="secondary" data-action="nav" data-id="receivables"><strong>${money(overdue.reduce((a,r)=>a+r.amount,0))}</strong><span>Em atraso · ${overdue.length} cobrança(s)</span></button><button class="secondary" data-action="nav" data-id="reservations"><strong>${arrivals.length}</strong><span>Entradas nos próximos 7 dias</span></button></div>`+lastView()}return lastView()};
async function opsSave(k,d){if(remote)return api(k+'/save',d);commitLocal(k==='reservations'?'Reserva cadastrada':'Cobrança cadastrada',d.guest||d.title,s=>{if(k==='reservations'){if(!d.guest.trim()||!d.arrival||!d.departure||d.arrival>=d.departure)throw Error('Confira hóspede e datas.');if(s[k].some(r=>r.property_id===d.property_id&&r.status!=='Cancelada'&&r.arrival<d.departure&&r.departure>d.arrival))throw Error('Já existe uma reserva neste período.')}else if(!d.title.trim()||!d.payer.trim()||!d.due||d.amount<=0)throw Error('Confira os dados da cobrança.');s[k].unshift({...d,id:nextId(s[k]),status:k==='reservations'?'Confirmada':'Aberta'})})}
async function opsStatus(k,id,status,d){if(remote)return api(k+'/status',{id,status,...d});commitLocal('Registro '+status,k,s=>{const r=s[k].find(x=>x.id===id);if(!r||!['Aberta','Confirmada'].includes(r.status))throw Error('Registro já encerrado.');if(status==='Concluída'&&r.departure>localDate())throw Error('A reserva ainda não terminou.');if(status==='Recebida'){if(!d.date||d.date>localDate())throw Error('Data de recebimento inválida.');const fid=nextId(s.finance);s.finance.unshift({id:fid,property_id:r.property_id,title:r.title,kind:'Receita',amount:r.amount,date:d.date});r.finance_id=fid}r.status=status})}
root.addEventListener('click',ev=>{const b=ev.target.closest('[data-action]');if(!b)return;const a=b.dataset.action,raw=b.dataset.id;if(!['ops-new','ops-status','property-open','property-section'].includes(a))return;ev.stopImmediatePropagation();try{if(a==='property-open'){selectedProperty=Number(raw);go('property');return}if(a==='property-section'){go(raw,String(selectedProperty));return}if(a==='ops-new'){if(!hasProps())return;const k=raw||page;const html=propSelect(filter)+(k==='reservations'?field('guest','Hóspede / responsável','text','',true)+field('arrival','Entrada','date',localDate(),true)+field('departure','Saída','date',dayOffset(1),true)+field('notes','Observações','textarea'):field('title','Descrição','text','',true)+field('payer','Pagador','text','',true)+field('amount','Valor (R$)','number','',true)+field('due','Vencimento','date',localDate(),true));modal(k==='reservations'?'Nova reserva':'Nova cobrança',html,d=>opsSave(k,{...ints(d,['property_id']),...(k==='receivables'?{amount:cents(d.amount)}:{})}));return}const [k,i,status]=raw.split(':');modal(status==='Recebida'?'Registrar recebimento':status==='Cancelada'?'Cancelar registro':'Concluir reserva',`<p>${status==='Recebida'?'O valor será lançado como receita uma única vez.':'A situação será atualizada e o histórico preservado.'}</p>`+(status==='Recebida'?field('date','Data de recebimento','date',localDate(),true):''),d=>opsStatus(k,Number(i),status,d))}catch(err){toast(err.message)}},true);

/* Navigation and original schematic illustrations. */
const premiumSearchIcon='<svg aria-hidden="true" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7"><circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/></svg>';
const jump=document.createElement('dialog');jump.className='jump-dialog';jump.setAttribute('aria-labelledby','jump-title');jump.innerHTML='<button class="secondary small jump-close" aria-label="Fechar busca">Fechar</button><h2 id="jump-title">Ir para uma área</h2><input type="search" placeholder="Ex.: reservas, contratos, imóveis" aria-label="Buscar módulo"><div class="jump-list"></div>';document.body.append(jump);const ji=jump.querySelector('input'),jl=jump.querySelector('.jump-list');let priorFocus=null;
function jumpResults(){const q=norm(ji.value.trim());jl.innerHTML=groups.flatMap(([g,links])=>links.filter(([k,l])=>!q||norm(l+' '+g).includes(q)).map(([k,l])=>`<button type="button" data-jump="${e(k)}">${e(l)}<small>${e(g)}</small></button>`)).join('')||'<p>Nenhuma área encontrada.</p>'}
function openJump(){if(jump.open||document.querySelector('dialog[open]'))return;priorFocus=document.activeElement;ji.value='';jumpResults();jump.showModal();ji.focus()}
ji.addEventListener('input',jumpResults);ji.addEventListener('keydown',ev=>{if(ev.key==='ArrowDown'){ev.preventDefault();jl.querySelector('button')?.focus()}if(ev.key==='Enter'){ev.preventDefault();jl.querySelector('button')?.click()}});jump.querySelector('.jump-close').onclick=()=>jump.close();jump.addEventListener('click',ev=>{const target=ev.target.closest('[data-jump]');if(target){jump.close();go(target.dataset.jump);document.querySelector('.breadcrumb strong')?.focus()}else if(ev.target===jump)jump.close()});jump.addEventListener('close',()=>{if(priorFocus?.isConnected)priorFocus.focus()});document.addEventListener('keydown',ev=>{if((ev.ctrlKey||ev.metaKey)&&ev.key.toLowerCase()==='k'&&!ev.altKey){ev.preventDefault();openJump()}});
const architectureArt=(kind)=>`<svg viewBox="0 0 240 132" fill="none" stroke="currentColor" aria-hidden="true"><g opacity=".22"><path d="M10 22h220M10 50h220M10 78h220M10 106h220M30 8v116M70 8v116M110 8v116M150 8v116M190 8v116M230 8v116"/></g><path opacity=".7" d="M13 115h214"/>${kind==='Casa'?'<path d="M38 114V59l62-43 62 43v55M30 62l70-50 70 50M49 114V65l51-36 51 36v49M72 114V79h26v35M114 75h26v22h-26zM127 75v22M114 86h26M162 114V79l28-19 26 19v35M180 114V91h18v23"/>':kind==='Kitnet'?'<path d="M37 114V53h164v61M30 53h178M44 45h150v8M51 63h30v31H51zM99 63h30v31H99zM147 63h38v51h-38zM66 63v31M114 63v31M166 63v51M35 104h102"/>':'<path d="M45 114V29l49-14 55 14v85M94 15v99M149 114V45l44 10v59M45 45l49-13 55 13M45 65l49-12 55 12M45 85l49-12 55 12M56 38v69M72 33v74M107 36v71M125 40v67M161 57v51M178 61v47M149 73l44 10M149 92l44 10M85 114V94h18v20"/>'}<path opacity=".55" stroke-dasharray="3 4" d="M17 12v102M13 12h9M13 114h9M17 8h207M224 4v8"/></svg>`;
const originalRenderPremium=render;render=function(){const prev=document.querySelector('.sidebar .nav')?.scrollTop||0;originalRenderPremium();const top=document.querySelector('.topright');if(top){const b=document.createElement('button');b.className='quick-search';b.type='button';b.setAttribute('aria-label','Buscar módulos');b.innerHTML=premiumSearchIcon+'<span>Buscar</span><kbd>Ctrl K</kbd>';b.onclick=openJump;top.prepend(b)}const n=document.querySelector('.sidebar .nav');if(n)n.scrollTop=prev;const v=document.querySelector('#view');const hero=v?.querySelector('.welcome'),alerts=v?.querySelector('.ops-alerts');if(hero&&alerts)v.insertBefore(hero,alerts);decorateProperties()};
function decorateProperties(){document.querySelectorAll('.property').forEach(card=>{const art=card.querySelector('.art'),kind=card.querySelector('.eyebrow')?.textContent;if(art&&!art.dataset.illustrated){art.dataset.illustrated='1';art.innerHTML=architectureArt(kind)+'<span class="premium-caption">Ilustração</span>'}})}
const originalWirePremium=wireFilters;wireFilters=function(){originalWirePremium();decorateProperties()};

const originalGoPremium=go;go=function(p,f=''){const changed=p!==page;originalGoPremium(p,f);if(changed)window.scrollTo({top:0,behavior:'instant'})};
jl.addEventListener('keydown',ev=>{const bs=[...jl.querySelectorAll('button')],i=bs.indexOf(document.activeElement);if(ev.key==='ArrowDown'||ev.key==='ArrowUp'){ev.preventDefault();const n=i+(ev.key==='ArrowDown'?1:-1);if(n<0)ji.focus();else bs[Math.min(n,bs.length-1)]?.focus()}});

let atelierArtSerial=0;const atelierScene=(kind='Apartamento',hero=false)=>{
 const house=kind==='Casa',studio=kind==='Kitnet';
 const front=house?'<path d="M73 165V99l68-47 68 47v66z" fill="#75817c"/><path d="m64 101 77-55 76 55" fill="none" stroke="#bac4bd" stroke-width="5"/><path d="M89 108h35v39H89zM151 108h42v39h-42z" fill="#242b29"/><path d="M129 165v-49h20v49" fill="#414d48"/><path d="M98 112h21v29H98zM157 113h30v28h-30z" fill="#d9c5a2"/>':studio?'<path d="M63 165V82h173v83z" fill="#687771"/><path d="M54 82h191v-8H54z" fill="#a8b5ad"/><path d="M80 94h55v56H80zM151 94h68v71h-68z" fill="#252e2b"/><path d="M86 100h43v44H86zM158 100h54v59h-54z" fill="#c8b99c"/><path d="M106 100v44M185 100v59" stroke="#53635b" stroke-width="3"/>':'<path d="M83 165V46l94-24 79 27v116z" fill="#606d68"/><path d="M177 22v143h79V49z" fill="#35413c"/><path d="M83 46l94-24v143H83z" fill="#829088"/><path d="M77 46l100-27 83 30" stroke="#bbc5bd" stroke-width="3" fill="none"/>'+[0,1,2,3].map(i=>`<g transform="translate(0 ${i*26})"><path d="M99 54l62-13v16l-62 13z" fill="${i===1?'#e2ca9d':'#35423d'}"/><path d="m189 43 51 17v15l-51-17z" fill="${i===2?'#bfb18f':'#242d29'}"/><path d="M122 50v15M143 46v15" stroke="#56665e" stroke-width="2"/></g>`).join('')+'<path d="M124 165v-27h28v27" fill="#394741"/>';
 const id='atelier'+(++atelierArtSerial);
 return `<svg ${hero?'class="architecture"':''} viewBox="0 0 320 200" preserveAspectRatio="xMidYMid slice" aria-hidden="true"><defs><linearGradient id="${id}sky" x1="0" y1="0" x2="1" y2="1"><stop stop-color="#2c3432"/><stop offset="1" stop-color="#191b1b"/></linearGradient><linearGradient id="${id}fade"><stop stop-color="#202222"/><stop offset=".46" stop-color="#202222" stop-opacity="0"/></linearGradient></defs><path fill="url(#${id}sky)" d="M0 0h320v200H0z"/><circle cx="246" cy="47" r="33" fill="#b0ada0" opacity=".68"/><path d="M0 157 52 112l42 30 47-50 60 41 63-59 56 39v87H0z" fill="#384440"/><path d="M0 165h320v35H0z" fill="#232928"/><g opacity=".7" fill="#505c56"><path d="M24 165V95l21-6v76zM46 165v-52l18-4v56zM272 165V104l24-15v76z"/></g>${front}<path d="M0 165h320" stroke="#8c9990" stroke-width="1"/><path d="m0 199 118-34m202 34-80-34M0 181h320M0 190h320" stroke="#45514a" stroke-width="1" fill="none"/><g stroke="#85988b" stroke-width="1.3" fill="none"><path d="M48 165v-37m0 16-10-9m10 4 12-13M276 165v-48m0 16-13-13m13 5 13-12"/></g><g fill="#65796c"><ellipse cx="39" cy="131" rx="7" ry="11"/><ellipse cx="57" cy="125" rx="9" ry="13"/><ellipse cx="267" cy="119" rx="9" ry="15"/><ellipse cx="286" cy="111" rx="10" ry="17"/></g>${hero?`<path fill="url(#${id}fade)" d="M0 0h320v200H0z"/>`:''}</svg>`;
};
const atelierClosed=new Set(['Administração','Conta']);
function atelierNav(){const n=document.querySelector('.sidebar .nav');if(!n)return;for(const label of [...n.querySelectorAll('.navlabel')]){const group=label.textContent.trim(), links=[];for(let b=label.nextElementSibling;b&&!b.classList.contains('navlabel');b=b.nextElementSibling)links.push(b);if(links.some(b=>b.classList.contains('active')))atelierClosed.delete(group);const t=document.createElement('button');t.type='button';t.className='section-toggle';t.innerHTML=`<span>${e(group)}</span><svg viewBox="0 0 20 20" fill="none" stroke="currentColor" stroke-width="1.6" aria-hidden="true"><path d="m5 7 5 5 5-5"/></svg>`;const sync=()=>{const closed=atelierClosed.has(group);t.setAttribute('aria-expanded',String(!closed));links.forEach(b=>b.hidden=closed)};t.addEventListener('click',()=>{atelierClosed.has(group)?atelierClosed.delete(group):atelierClosed.add(group);sync()});label.replaceWith(t);sync()}}
function atelierVisuals(){const hero=document.querySelector('#view .welcome');if(hero){if(!hero.dataset.atelier){hero.dataset.atelier='1';hero.querySelector('.architecture')?.remove();hero.insertAdjacentHTML('beforeend',atelierScene('Casa',true))}const metrics=document.querySelector('#view .metric-grid'),alerts=document.querySelector('#view .ops-alerts');if(metrics){metrics.before(hero);if(alerts)metrics.after(alerts)}}document.querySelectorAll('.property .art').forEach((art,i)=>{if(art.dataset.atelier)return;art.dataset.atelier='1';const kind=art.closest('.property')?.querySelector('.eyebrow')?.textContent;art.innerHTML=atelierScene(kind)+'<span class="premium-caption">Ilustração</span>'})}
const renderBeforeAtelier=render;render=function(){renderBeforeAtelier();atelierNav();atelierVisuals()};const wireBeforeAtelier=wireFilters;wireFilters=function(){wireBeforeAtelier();atelierVisuals()};

